<script setup lang="ts">
import { computed, ref } from "vue"; import { http } from "@/utils/http";
type Dictionary = Record<string, any>; const rows = ref<Dictionary[]>([]); const selected = ref<Dictionary | null>(null); const loading = ref(false); const error = ref(""); const query = ref(""); const entryDialog = ref(false); const entry = ref({ value: "", label: "", description: "", sortOrder: 0, enabled: true }); const dictionaries = computed(() => rows.value.filter(item => !query.value || String(item.name || item.key || "").toLowerCase().includes(query.value.toLowerCase())));
async function load() { loading.value = true; try { const result: any = await http.get("/platform/dictionaries"); rows.value = Array.isArray(result) ? result : (result?.content || result?.items || []); selected.value = rows.value[0] || null; } catch (e: any) { error.value = e?.response?.data?.detail || "受控字典接口尚未接入"; } finally { loading.value = false; } } load();
</script>
<template><main class="p-4 md:p-6"><div class="flex justify-between items-start mb-6"><div><h1 class="text-2xl font-semibold">数据字典</h1><p class="mt-1 text-[var(--el-text-color-secondary)]">仅管理产品明确设计为运行时可配置的受控字典，不是通用 SQL 表编辑器。</p></div><el-button :loading="loading" @click="load">刷新</el-button></div><el-alert v-if="error" :title="error" type="warning" show-icon :closable="false" class="mb-4"/><el-skeleton v-if="loading" :rows="8" animated/><div v-else class="grid grid-cols-1 md:grid-cols-3 gap-5"><el-card shadow="never"><template #header><div class="flex justify-between items-center"><span>Dictionary</span><el-input v-model="query" clearable placeholder="搜索字典" class="w-32"/></div></template><el-empty v-if="!dictionaries.length" description="暂无字典目录"/><div v-for="item in dictionaries" :key="item.id || item.key" class="p-3 rounded cursor-pointer" :class="selected === item ? 'bg-[var(--el-fill-color-light)]' : ''" @click="selected = item"><div class="font-medium">{{ item.name || item.key }}</div><div class="text-xs text-[var(--el-text-color-secondary)] mt-1">{{ item.entryCount ?? item.entries?.length ?? 0 }} entries · {{ item.subsystem || '—' }} · {{ item.source || 'System' }}</div><div class="text-xs mt-1">{{ item.updatedAt || '—' }}</div></div></el-card><el-card shadow="never" class="md:col-span-2"><template #header><div class="flex justify-between"><div><div class="font-medium">{{ selected?.name || '选择一个字典' }}</div><div class="text-xs text-[var(--el-text-color-secondary)] mt-1">{{ selected?.key || '' }}</div></div><el-button type="primary" :disabled="!selected || selected.source === 'SYSTEM'" @click="entryDialog = true">新增 Entry</el-button></div></template><el-empty v-if="!selected" description="选择左侧字典查看 Entry"/><template v-else><el-table :data="selected.entries || []" stripe><el-table-column label="Value / Key" min-width="180"><template #default="{ row }"><span class="font-mono">{{ row.value || row.key }}</span></template></el-table-column><el-table-column prop="label" label="Display Label" min-width="180"/><el-table-column prop="localizedLabel" label="Localized Label" min-width="160"/><el-table-column prop="description" label="描述" min-width="220"/><el-table-column prop="sortOrder" label="Sort Order" width="100"/><el-table-column prop="enabled" label="启用" width="90"/><el-table-column prop="source" label="来源" width="100"/><el-table-column prop="referenceCount" label="引用数" width="90"/><el-table-column label="操作" width="100"><template #default="{ row }"><el-button link :disabled="row.source === 'SYSTEM'">编辑</el-button></template></el-table-column></el-table><el-alert title="System-owned Entry 默认只读；禁用不会影响已有引用。删除有引用的 Entry 必须先选择替换目标。" type="info" show-icon class="mt-4"/></template></el-card></div><el-dialog v-model="entryDialog" title="Entry 编辑器" width="520px"><el-form label-position="top"><el-form-item label="Value / Key" required><el-input v-model="entry.value"/></el-form-item><el-form-item label="默认 Label" required><el-input v-model="entry.label"/></el-form-item><el-form-item label="Localized Label"><el-input/></el-form-item><el-form-item label="描述"><el-input v-model="entry.description" type="textarea"/></el-form-item><el-form-item label="Sort Order"><el-input-number v-model="entry.sortOrder"/></el-form-item><el-form-item><el-switch v-model="entry.enabled" active-text="Enabled"/></el-form-item></el-form><template #footer><el-button @click="entryDialog = false">取消</el-button><el-button type="primary" disabled>保存</el-button></template></el-dialog></main></template>
